-- A delivery billed on an invoice of its own is signed on its own, so it has its own stages on the order's timeline. They are separate
-- from kra_signed / kra_failed because those mirror the goods invoice onto orders.kra_transmission_status.
ALTER TABLE "order_stage_events" DROP CONSTRAINT "order_stage_events_stage_chk";--> statement-breakpoint
ALTER TABLE "order_stage_events" ADD CONSTRAINT "order_stage_events_stage_chk" CHECK ("stage" IN ('checkout_started','checkout_validated','checkout_refused','order_placed','charge_quoted','pricing_applied','stock_reserved','reservation_failed','stock_issued','stock_released','stock_returned','approval_requested','approval_approved','approval_rejected','approval_escalated','approval_reopened','approval_withdrawn','payment_started','prompt_sent','payment_pending_verification','payment_confirmed','payment_failed','payment_expired','payment_retried','payment_reconciled','payment_discrepancy','refund_requested','refund_completed','refund_failed','released_for_fulfilment','blocked','unblocked','pick_started','picked','packed','ready','dispatched','out_for_delivery','delivery_attempted','delivered','delivery_failed','returned_to_stock','collected','invoice_issued','kra_submitted','kra_signed','kra_failed','delivery_invoice_signed','delivery_invoice_failed','delivery_invoice_skipped','credit_note_issued','completed','cancelled','failed','refunded','status_corrected','unrecorded_change'));
